<?php defined('BASEPATH') or exit('No direct script access allowed');$company_page_title='Copiar despesa';require APPPATH.'views/admin/includes/native_company_official_head.php';$esc=static fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');$url=fn($q='')=>CompanyRequestScope::adminUrl($this,'expenses/copy?source=company'.$q);$expenseUrl=fn($id)=>CompanyRequestScope::adminUrl($this,'expenses?source=company&expense='.NativeCompanyResourceId::encode('company_expense',$id));$sourceUrl=fn($id)=>CompanyRequestScope::adminUrl($this,'expenses?source=company&expense='.$id);$labels=['category_id'=>'Categoria','client_id'=>'Cliente','project_id'=>'Projeto','currency'=>'Moeda','date'=>'Data','description'=>'Descrição','note'=>'Observação','amount'=>'Valor base','tax_rate'=>'Tributo adicional (%)'];
