<?php if($receipt){?><div id="expense-copy-receipt"><h2>Cópia confirmada</h2><p>Chave: <?= $esc($receipt['request_key']); ?></p><a id="expense-copy-result" href="<?= $esc($expenseUrl($receipt['expense_id'])); ?>">Abrir nova despesa</a><h3>Estado atual da nova despesa</h3><?php $summary($receipt['current']); ?><h3>Origem preservada na confirmação</h3><?php $summary($receipt['source']); ?><p>Estado atual da origem: <?= $esc($receipt['source_state']); ?></p><h3>Dados confirmados da nova despesa</h3><p>Categoria confirmada: <?= $esc($receipt['reference_names']['category_name']); ?></p><?php $summary($receipt['creation']); ?></div><?php } ?>
<?php if($preview){?><h2>Origem preservada</h2><div id="expense-copy-source"><?php $summary($preview['source']); ?></div><p><a href="<?= $esc($sourceUrl($source)); ?>">Abrir origem</a></p>
<?php if($review){?><h2>Conferir destino antes de registrar</h2><div id="expense-copy-confirmation"><dl><?php foreach($labels as$f=>$label){?><dt><?= $esc($label); ?></dt><dd><?= $esc($review['input'][$f]); ?><?php $name=match($f){'category_id'=>'category_name','client_id'=>'client_name','project_id'=>'project_name',default=>null};if($name){?> · <?= $esc($review['reference_names'][$name]); ?><?php } ?></dd><?php } ?><dt>Tributo / total</dt><dd><?= $esc($review['tax'].' / '.$review['total']); ?></dd></dl><?= form_open($url(),['id'=>'expense-copy-confirm']);$hidden('copy_reviewed_expense'); ?><input type="hidden" name="request_key" value="<?= $esc($request_key); ?>"><input type="hidden" name="review[source_revision]" value="<?= $esc($review['source_revision']); ?>"><input type="hidden" name="review[reference_revision]" value="<?= $esc($review['reference_revision']); ?>"><?php foreach($labels as$f=>$label){?><input type="hidden" name="review[input][<?= $esc($f); ?>]" value="<?= $esc($review['input'][$f]); ?>"><?php } ?><label><input type="checkbox" name="review[confirm]" value="1" required> Conferi a origem, as referências atuais e os valores do novo custo independente.</label><button type="submit">Confirmar nova despesa</button><?= form_close(); ?></div><?php } ?>
<h2>Dados da nova despesa</h2><?= form_open($url(),['id'=>'expense-copy-review']);$hidden('review_expense_copy'); ?><input type="hidden" name="source_revision" value="<?= $esc($preview['source_revision']); ?>">
<?php foreach(['category_id'=>['Categoria ativa',$preview['categories'],'id','name'],'client_id'=>['Cliente autorizado (opcional)',$preview['clients'],'userid','company'],'project_id'=>['Projeto ativo do cliente (opcional)',$preview['projects'],'id','name']]as$f=>[$label,$options,$idField,$nameField]){?><label for="expense-copy-<?= $esc($f); ?>"><?= $esc($label); ?></label><select id="expense-copy-<?= $esc($f); ?>" name="expense[<?= $esc($f); ?>]" class="form-control" <?= $f==='category_id'?'required':''; ?>><option value="<?= $f==='category_id'?'':'0'; ?>"><?= $f==='category_id'?'Selecione categoria atual':'Sem vínculo'; ?></option><?php $visibleIds=array_map(static fn($o)=>(int)$o[$idField],array_values(array_filter($options,static fn($o)=>$f!=='category_id'||(int)$o['active']===1)));if((int)($values[$f]??0)!==0&&!in_array((int)$values[$f],$visibleIds,true)){?><option selected value="<?= (int)$values[$f]; ?>">Referência anterior indisponível: selecione referência atual ou remova o vínculo opcional</option><?php }foreach($options as$o){if($f==='category_id'&&!(int)$o['active'])continue;?><option value="<?= (int)$o[$idField]; ?>" <?= (int)($values[$f]??0)===(int)$o[$idField]?'selected':''; ?>><?= $esc($o[$nameField]); ?></option><?php } ?></select><?php } ?>
<label for="expense-copy-description">Descrição</label><input id="expense-copy-description" name="expense[description]" maxlength="191" value="<?= $esc($values['description']??''); ?>" required class="form-control"><label for="expense-copy-date">Data da nova despesa</label><input id="expense-copy-date" name="expense[date]" type="date" min="2000-01-01" max="2100-12-31" value="<?= $esc($values['date']??''); ?>" required class="form-control"><label for="expense-copy-currency">Moeda</label><select id="expense-copy-currency" name="expense[currency]" class="form-control"><?php foreach(['BRL','USD','EUR']as$c){?><option <?= ($values['currency']??'')===$c?'selected':''; ?>><?= $c; ?></option><?php } ?></select>
<?php foreach(['amount'=>'Valor base (decimal com ponto)','tax_rate'=>'Tributo adicional (%)']as$f=>$label){?><label for="expense-copy-<?= $esc($f); ?>"><?= $esc($label); ?></label><input id="expense-copy-<?= $esc($f); ?>" name="expense[<?= $esc($f); ?>]" inputmode="decimal" pattern="[0-9]+(\.[0-9]{1,2})?" value="<?= $esc($values[$f]??''); ?>" required class="form-control"><?php } ?><p>O tributo adicional é somado à base. A revisão mostra o total calculado antes da confirmação.</p><label for="expense-copy-note">Observação</label><textarea id="expense-copy-note" name="expense[note]" maxlength="4000" class="form-control"><?= $esc($values['note']??''); ?></textarea><button type="submit">Revisar nova despesa</button><?= form_close(); ?><?php } ?></section><?php require APPPATH.'views/admin/includes/native_company_official_tail.php'; ?>
